const views=[...document.querySelectorAll('.view')], crumb=document.getElementById('crumb'), modal=document.getElementById('modal'), toast=document.getElementById('toast');
const labels={home:'OVERVIEW',workout:'ACTIVE WORKOUT',history:'HISTORY',progress:'PROGRESS',plan:'PLANS & ROUTINES',manage:'EXERCISE LIBRARY',profile:'PROFILE & SETTINGS'};
function note(message='Sample interaction — no real data saved'){toast.textContent=message;toast.classList.add('show');clearTimeout(note.t);note.t=setTimeout(()=>toast.classList.remove('show'),2200)}
function navigate(id){views.forEach(v=>v.classList.toggle('active',v.id==='view-'+id));document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===id));crumb.textContent=labels[id]||id.toUpperCase();document.querySelector('.content').scrollTop=0;window.scrollTo(0,0);document.querySelector('.sidebar').classList.remove('open')}
document.addEventListener('click',e=>{const btn=e.target.closest('[data-view]');if(btn){navigate(btn.dataset.view);return}});
document.getElementById('side-nav').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b)navigate(b.dataset.view)});
function openModal(title,desc='This prototype uses sample data only. Nothing is saved to your account.'){document.getElementById('modal-title').textContent=title;document.getElementById('modal-desc').textContent=desc;modal.classList.add('open')}
document.getElementById('modal-close').onclick=()=>modal.classList.remove('open');modal.addEventListener('click',e=>{if(e.target===modal)modal.classList.remove('open')});
document.getElementById('modal-confirm').onclick=()=>{modal.classList.remove('open');note('Sample preview only — no real data saved')};
document.getElementById('log-set').onclick=()=>openModal('Log a set');document.querySelectorAll('.add-set').forEach(b=>b.onclick=()=>openModal('Log a set'));
document.querySelectorAll('#finish,#finish2').forEach(b=>b.onclick=()=>openModal('Finish workout?','Workout summary preview: 52 min · 6 exercises · 14 sets · 1 new PR. No workout is saved.'));
document.querySelectorAll('#add-exercise,#library-add-exercise').forEach(b=>b.onclick=()=>openModal('Add exercise','Search the sample exercise library, choose a category, and add to this session.'));
document.getElementById('new-routine').onclick=()=>openModal('Create routine','Sample routine builder: name, add/reorder exercises, choose training days.');document.getElementById('create-routine').onclick=()=>openModal('Create routine','Sample routine builder: name, add/reorder exercises, choose training days.');
document.getElementById('edit-split').onclick=()=>openModal('Edit weekly split','Assign routines to training days, change categories, or set rest days.');document.querySelectorAll('.edit-routine').forEach(b=>b.onclick=()=>openModal('Edit routine','Reorder or remove exercises, duplicate the routine, or change its schedule.'));
document.getElementById('new-category').onclick=()=>openModal('Create category','Add a named category, choose its color, and assign a training split.');document.querySelectorAll('.edit-exercise').forEach(b=>b.onclick=()=>openModal('Edit exercise','Change exercise name, category, muscle associations, or ordering.'));
document.getElementById('edit-goal').onclick=()=>openModal('Edit exercise goal','Set target weight, reps, and kg/lb unit.');document.getElementById('log-weight').onclick=()=>openModal('Log body weight','Sample body-weight entry and weigh-in history.');
document.getElementById('export').onclick=()=>openModal('Export workout history','Choose CSV or JSON and a date range. Sample export only; no file is generated.');document.getElementById('export2').onclick=()=>openModal('Export your data','Choose CSV or JSON and a date range. Sample export only; no file is generated.');
document.getElementById('signout').onclick=()=>openModal('Sign out?','Sign-out confirmation concept. This preview does not connect to an account.');document.getElementById('delete-account').onclick=()=>openModal('Delete account','Account deletion confirmation concept — no account action is performed.');document.getElementById('forgot').onclick=()=>openModal('Reset password','Password reset confirmation concept. No email is sent in this prototype.');document.getElementById('preview-auth').onclick=()=>openModal('Sign in to LIFTS','Email and password, create account, forgot password, and Google sign-in are part of the real app. This visual preview is not connected to Firebase.');
document.querySelectorAll('.timer-presets button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.timer-presets button').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');let n=b.textContent==='60s'?60:b.textContent==='90s'?90:b.textContent==='2m'?120:180;timerLeft=n;drawTimer();note('Rest timer preset updated')});let timerLeft=84;function drawTimer(){const el=document.querySelector('.timer');el.textContent=String(Math.floor(timerLeft/60)).padStart(2,'0')+':'+String(timerLeft%60).padStart(2,'0')}document.getElementById('timer-add').onclick=()=>{timerLeft+=30;drawTimer();note('30 seconds added')};document.getElementById('timer-stop').onclick=()=>{timerLeft=0;drawTimer();note('Rest timer stopped')};setInterval(()=>{if(timerLeft>0){timerLeft--;drawTimer()}},1000);
document.querySelectorAll('.check-set').forEach(b=>b.onclick=()=>{b.classList.toggle('done');b.textContent=b.classList.contains('done')?'✓':'○';note('Set status toggled — sample only')});document.querySelectorAll('.expand').forEach(b=>b.onclick=()=>{b.textContent=b.textContent==='⌄'?'⌃':'⌄';note('Workout details expanded — sample data')});document.querySelectorAll('.chips button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.chips button').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');note('Exercise filter: '+b.childNodes[0].textContent.trim())});document.querySelectorAll('.unit-toggle button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.unit-toggle button').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');note('Display unit set to '+b.dataset.unit+' — sample only')});let restCount=2;document.getElementById('rest-minus').onclick=()=>{restCount=Math.max(0,restCount-1);document.getElementById('rest-count').textContent=restCount;note('Rest day preference changed — sample only')};document.getElementById('rest-plus').onclick=()=>{restCount=Math.min(7,restCount+1);document.getElementById('rest-count').textContent=restCount;note('Rest day preference changed — sample only')};document.getElementById('menu').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');
const heat=document.getElementById('heatmap');for(let i=0;i<182;i++){const cell=document.createElement('i'),v=Math.random();if(v>.82)cell.className='l4';else if(v>.68)cell.className='l3';else if(v>.50)cell.className='l2';else if(v>.36)cell.className='l1';heat.append(cell)}
